<?php
declare(strict_types=1);
require_once __DIR__ . '/config/inventory_step13.php';
$error=null;$rows=[];$ledger=[];$view=(string)($_GET['view']??'stock');if(!in_array($view,['stock','ledger'],true))$view='stock';
try{
 $pdo=business_db();inventory_step13_ensure($pdo);$ctx=inventory_step13_context($pdo);$orgId=(int)$ctx['organization_id'];$locationId=(int)$ctx['location_id'];$rows=inventory_step13_stock_rows($pdo,$orgId,$locationId);
 $stmt=$pdo->prepare("SELECT t.id,t.movement_date,t.movement_type,t.quantity_delta,t.unit_cost,t.reference_type,t.reference_id,t.source_reference,t.notes,p.product_name,p.sku,b.batch_code,b.expiry_date FROM inventory_transactions t JOIN products p ON p.id=t.product_id LEFT JOIN inventory_batches b ON b.id=t.batch_id WHERE t.organization_id=? AND t.location_id=? ORDER BY t.movement_date DESC,t.id DESC");$stmt->execute([$orgId,$locationId]);$ledger=$stmt->fetchAll();
 if(($_GET['format']??'')==='csv'){
  $filename=$view==='stock'?'inventory-current-stock.csv':'inventory-ledger.csv';header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="'.$filename.'"');echo "\xEF\xBB\xBF";$out=fopen('php://output','w');
  if($view==='stock'){fputcsv($out,['Stock No.','Product','Sellable','Total','Expired','Live Batches','Next Expiry','Reorder Level','Target Stock','Known Value']);foreach($rows as $r)fputcsv($out,[$r['sku'],$r['product_name'],$r['sellable_stock'],$r['stock_total'],$r['expired_stock'],$r['live_batches'],$r['next_expiry'],$r['reorder_level'],$r['target_stock'],$r['known_value']]);}
  else{fputcsv($out,['Transaction ID','Date','Type','Stock No.','Product','Batch','Expiry','Quantity Delta','Unit Cost','Reference Type','Reference ID','Source Reference','Notes']);foreach($ledger as $r)fputcsv($out,[$r['id'],$r['movement_date'],$r['movement_type'],$r['sku'],$r['product_name'],$r['batch_code'],$r['expiry_date'],$r['quantity_delta'],$r['unit_cost'],$r['reference_type'],$r['reference_id'],$r['source_reference'],$r['notes']]);}
  fclose($out);exit;
 }
}catch(Throwable $e){$error=$e->getMessage();}
function ex_h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}function ex_n(mixed $v):string{$x=number_format((float)$v,3,'.','');return rtrim(rtrim($x,'0'),'.');}function ex_m(mixed $v):string{return '₹'.number_format((float)$v,2,'.',',');}
?>
