<header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="inventory_center.php"><img src="../img/logo.png" alt="logo"><span><strong>Healthcare Wellness Club</strong><small>STEP 13 • Inventory Export</small></span></a><div class="os-top-actions"><a class="os-btn" href="?view=<?= ex_h($view) ?>&format=csv">Download CSV</a><button class="os-btn" onclick="window.print()">Print / Save PDF</button><a class="os-btn primary" href="inventory_center.php">Inventory</a></div></div></header>
<div class="os-layout"><aside class="os-sidebar"><div class="os-nav-label">Inventory</div><nav class="os-nav"><a href="inventory_center.php"><i class="dot"></i>Inventory Center</a><a href="inventory_analytics.php"><i class="dot"></i>Analytics</a><a class="active" href="inventory_export.php"><i class="dot"></i>Export / Print</a><a href="step13_audit.php"><i class="dot"></i>STEP 13 Audit</a></nav></aside>
<main class="os-main"><section class="os-hero pp-hero no-print"><div class="os-kicker">STEP 13G • EXPORT & SHARE</div><h1>Export current stock or the full movement ledger.</h1><p>CSV is UTF-8 for spreadsheet use; Print / Save PDF uses the same visible source data.</p><div class="os-status-row"><span class="os-chip <?= $error===null?'good':'' ?>"><?= $error===null?'INVENTORY EXPORT LIVE':'Review required' ?></span><span class="os-chip"><?= count($rows) ?> stock rows</span><span class="os-chip"><?= count($ledger) ?> ledger movements</span></div></section>
<?php if($error):?><div class="pp-alert bad"><strong>Export diagnostic:</strong> <?= ex_h($error) ?></div><?php else:?><section class="os-card" style="margin-top:14px"><div class="os-title-row no-print"><div><h2><?= $view==='stock'?'Current Stock':'Stock Ledger' ?></h2></div><div><a class="os-btn <?= $view==='stock'?'primary':'' ?>" href="?view=stock">Current Stock</a> <a class="os-btn <?= $view==='ledger'?'primary':'' ?>" href="?view=ledger">Ledger</a></div></div><div class="pp-table-wrap"><table class="pp-table"><?php if($view==='stock'):?><thead><tr><th>Stock</th><th>Product</th><th>Sellable</th><th>Total</th><th>Expired</th><th>Batches</th><th>Next Expiry</th><th>Known Value</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?= ex_h($r['sku']) ?></b></td><td><?= ex_h($r['product_name']) ?></td><td><?= ex_h(ex_n($r['sellable_stock'])) ?></td><td><?= ex_h(ex_n($r['stock_total'])) ?></td><td><?= ex_h(ex_n($r['expired_stock'])) ?></td><td><?= number_format((int)$r['live_batches']) ?></td><td><?= ex_h($r['next_expiry']?:'—') ?></td><td><?= ex_m($r['known_value']) ?></td></tr><?php endforeach;?></tbody><?php else:?><thead><tr><th>ID</th><th>Date</th><th>Type</th><th>Product</th><th>Batch</th><th>Delta</th><th>Cost</th><th>Reference</th></tr></thead><tbody><?php foreach($ledger as $r):?><tr><td>#<?= (int)$r['id'] ?></td><td><?= ex_h($r['movement_date']) ?></td><td><?= ex_h(strtoupper(str_replace('_',' ',$r['movement_type']))) ?></td><td><b><?= ex_h($r['sku']) ?></b><small><?= ex_h($r['product_name']) ?></small></td><td><?= ex_h($r['batch_code']?:'—') ?></td><td><b><?= (float)$r['quantity_delta']>0?'+':'' ?><?= ex_h(ex_n($r['quantity_delta'])) ?></b></td><td><?= $r['unit_cost']!==null?ex_m($r['unit_cost']):'—' ?></td><td><?= ex_h($r['source_reference']?:(($r['reference_type']?:'').($r['reference_id']?' #'.$r['reference_id']:''))) ?></td></tr><?php endforeach;?></tbody><?php endif;?></table></div></section><?php endif;?>
<div class="os-footer-note"><strong>Export policy:</strong> inventory valuation shown here includes only batches with an explicit unit cost.</div></main></div><script src="assets/business-collapsible.js?v=20260820-1" defer></script></body></html>
